def strip_fences(s):
    lines=s.splitlines(keepends=True); out=[]; fence=None
    for line in lines:
        bare=line.rstrip('\\r\\n')
        if fence is None:
            m=re.match(r'"'^[ '"\\t]{0,3}("'```|~~~)'"', bare)
            if m: fence=m.group(1)
            else: out.append(line)
        elif re.match(r'"'^[ '"\\t]{0,3}'+re.escape(fence)+r'[ \\t]*"'$'"', bare):
            fence=None
    return ''.join(out)

def declaration(t):
    for line in t.splitlines():
        if line == '<"'!-- converge: required -->'"': return ('required',False)
        if line.startswith('<"'!-- converge: not-required'"') and line.endswith('-->'):
            inner=line[len('<"'!-- converge: not-required'"'):-3].strip()
            mr=re.search(r'(?:"'^|[ ;|])reason:'"\\s*(.*?)(?=(?:[ ;|]+decided-by:)|"'$)'"',inner)
            md=re.search(r'(?:"'^|[ ;|])decided-by:'"\\s*(.*?)(?=(?:[ ;|]+reason:)|"'$)'"',inner)
            return ('not-required', bool(mr and mr.group(1).strip() and md and md.group(1).strip()))
    return (None,False)

def marker(t): return re.search(r'(?:収束 receipt|converge receipt|/converge receipt)(?"'!'"\\w)',t,re.I) is not None
def round_label(t): return re.search(r'(?:周回|round)\\s*(?:\\d|軌跡)',t,re.I) is not None
def valid_body(body):
    return bool(re.search(r'判定.{0,12}?(?:収束|未収束)',body,re.S) and '起動経路' in body and round_label(body) and '未収束' in body and re.search(r'DoD.{0,400}?[✔✘]',body,re.S|re.I))
def receipt(t,n):
    if n<53: return marker(t) and round_label(t) and '未収束' in t
    lines=t.splitlines(keepends=True); hs=[]
    for i,line in enumerate(lines):
        m=re.match(r'"'^[ '"\\t]{0,3}(#{2,6})[ \\t]+(.*?)(?:\\r?\\n)?"'$'"',line)
        if m: hs.append((i,len(m.group(1)),m.group(2)))
    for pos,(i,d,title) in enumerate(hs):
        if marker(title):
            end=len(lines)
            for j,d2,_ in hs[pos+1:]:
                if d2<=d: end=j; break
            if valid_body(''.join(lines[i:end])): return True
    return False

for k,(n,s) in samples.items():
    hard=bool(('裁定をお願い' in s) or ('裁定を求め' in s) or re.search(r'gate\\s*①',s) or ('裁定対象' in s) or ('残ゲート' in s) or re.search(r'推奨(?:\\)|）|:|：)',s))
    clean=strip_fences(s); decl,ground=declaration(clean)
    conflict=decl=='not-required' and hard and not ground
    exempted=decl=='not-required' and hard and ground
    required=(hard and not exempted) or decl=='required'
    rec=receipt(clean,n) if required else None
    verdict='FAIL' if conflict else ('PASS' if not required or rec else 'FAIL')
    print(k, verdict, f'hard={hard} decl={decl} grounded={ground} conflict={conflict} required={required} receipt={rec}')
